ample.com., type=A, data=1.2.3.4)'}], 'expected': "Zone contains a single RRset for name 'example.com.' type A with exactly one record (the duplicate is ignored).", 'description': 'If the same Record instance (or an equal Record) is added twice, RRset.addRR should not create a duplicate entry. The test first adds the record, then calls addRecord again with an identical record and verifies that the RRset size remains 1.'}]}, {'group': 'AddRecord_ConcurrentAdditions', 'cases': [{'input': [{'parameter': 'recordThread1', 'value': 'Record(name=example.com., type=A, data=9.9.9.9)'}, {'parameter': 'recordThread2', 'value': 'Record(name=example.com., type=A, data=10.10.10.10)'}], 'expected': "After both threads complete, the zone contains a single RRset for name 'example.com.' type A with both records (9.9.9.9 and 10.10.10.10). No race condition or lost update occurs.", 'description': 'addRecord synchronizes on the Zone instance. This test spawns two threads that simultaneously invoke addRecord with different A records for the same name. The final state must include both records, proving that the synchronization prevents corruption.'}]}]
